import{_ as a,c as i,o as t,ah as o}from"./chunks/framework.CdwlI3v5.js";const m=JSON.parse('{"title":"Music","description":"","frontmatter":{"title":"Music","aside":false},"headers":[],"relativePath":"music.md","filePath":"music.md"}'),n={name:"music.md"};function h(r,e,l,s,d,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h2 style="text-align:center;">Repertoire</h2><ul><li>Liszt - Hungarian Rhapsody No. 2</li><li>Mozart - Piano Sonata No. 14 in C minor, K. 457</li><li>Chopin - Nocturne in C minor Op. 48 No. 1</li><li>Scarlatti - Cat Fugue</li><li>Beethoven - Piano Sonata No. 8 &quot;Pathétique&quot;</li><li>Rachmaninoff - Prelude in G minor</li><li>Liszt/Schubert - Erlkönig</li><li>Liszt - La Campanella</li><li>Rachmaninoff - Prelude in B minor</li><li>Liszt/Saint Seans - Danse Macabre</li><li>Liszt - Transcendental Études no. 4 &quot;Mazeppa&quot;</li><li>Chopin - Fantasie Impromptu</li><li>Chopin - Étude Op. 25 No. 6 &quot;Thirds&quot;</li><li>Grażyna Bacewicz - 10 Studies for piano no. 6</li><li>Liszt - Hungarian Rhapsody No. 6</li><li>Liszt - Transcendental Études no. 6 &quot;Vision&quot;</li><li>Rachmaninoff - Études-Tableaux Op. 39 No. 6 &quot;Little Red Riding Hood&quot;</li></ul><h2 style="text-align:center;">Compositions</h2><h3 id="der-gevatter-tod" tabindex="-1">Der Gevatter Tod <a class="header-anchor" href="#der-gevatter-tod" aria-label="Permalink to “Der Gevatter Tod”">​</a></h3><p>This is about a story of a physician, who was the 13th child in a poor family and Death. The key of this piece is in D minor - a prominent key for works relating to death. However, the physician is in Eb major. The father starts off by looking for a godfather and after rejecting God and the Devil, the physician&#39;s theme first appears in the piano as the father accepted Death as the godfather.</p><p>After the physician grows up, Death enters with a waltz which highlights the second main theme - the Dies Irae motif and the clashing key centres of D and Eb and a low F that will soon signify someone is about to die. This allows the physician to know if a person will die or survive, which quickly became famous as the orchestra reappears in a similar waltz.</p><p>Soon, the King fell ill and the low F naturals are heard. However, the physician decides to trick Death as he was his godson and hoped that Death will give him a chance and cures the King. Death gets angry over this and the Dies Irae motif can be heard before the piano comes in where Death warns the physician that this will be his only chance.</p><p>Next, the King&#39;s daughter fell ill and promises anyone who rescued her will get to become her husband and get the crown. As the physician was too captured by this offer, he completely ignored Death and went to rescue her. However, Death would not give him another chance and drags him down to a cavern.</p><p>In the cavern, candles represent how long a person has left to live and flames jumped around and extinguished as people are born and die. The physician asks to see his candle and Death showed a candle that was about to get extinguished. This made him extremely scared and he begged Death to relight a candle for him. Death, wanting revenge, tricks the physician to think that he will have a new candle but slips, killing the physician.</p><p><a href="/static/music/Der%20Gevatter%20Tod.pdf">Score</a>   <a href="/static/music/Der%20Gevatter%20Tod.mp3">Audio</a></p><h3 id="mary-had-a-little-lamb" tabindex="-1">Mary had a little lamb <a class="header-anchor" href="#mary-had-a-little-lamb" aria-label="Permalink to “Mary had a little lamb”">​</a></h3><p>had</p><p><a href="/static/music/Mary%20had%20a%20little%20lamb.pdf">Score</a>   <a href="/static/music/Mary%20had%20a%20little%20lamb.mp3">Audio</a></p><h3 id="modulation-waltz" tabindex="-1">Modulation waltz <a class="header-anchor" href="#modulation-waltz" aria-label="Permalink to “Modulation waltz”">​</a></h3><p>A waltz that modulates through every key!</p><p><a href="/static/music/Modulation%20waltz.pdf">Score</a>   <a href="/static/music/Modulation%20waltz.mp3">Audio</a></p><h3 id="elegy-in-a-minor" tabindex="-1">Elegy in A minor <a class="header-anchor" href="#elegy-in-a-minor" aria-label="Permalink to “Elegy in A minor”">​</a></h3><p><a href="/static/music/Elegy%20in%20A%20minor.pdf">Score</a>   <a href="/static/music/Elegy%20in%20A%20minor.mp3">Audio</a></p>',18)])])}const u=a(n,[["render",h]]);export{m as __pageData,u as default};
